  const applicationCaseContent={"new-energy":[{"id":"connector","title":"新能源防水连接器","image":"cases/energy-connector.webp","material":"PA6 GF30","problem":"电气绝缘、密封装配与户外暴露需要同时满足。","approach":"官网案例采用玻纤增强 PA6，并将阻燃、耐候与电气要求纳入同一材料方案。","validation":"核对实际壁厚下的阻燃、电气性能，以及成型件老化后的密封和关键尺寸。","ids":[],"source":"https://www.techinherit.com/new-energy-cases.html"},{"id":"motor-cover","title":"电机端盖","image":"cases/energy-motor.webp","material":"PPS GF40","problem":"持续热环境下，需要保持安装位置、刚性与配合精度。","approach":"官网案例采用 PPS GF40；选型重点是耐热、低吸湿和尺寸稳定的组合。","validation":"按实际温度与紧固载荷验证变形、热循环、蠕变和装配；具体体系可另行咨询。","ids":[],"source":"https://www.techinherit.com/new-energy-cases.html"}],"ai-hardware":[{"id":"fan-cover","title":"服务器风扇罩","image":"cases/ai-fan.webp","material":"PBT GF30 FR","problem":"轻量薄壁结构需兼顾刚性、尺寸稳定与运行可靠性。","approach":"官网案例采用阻燃增强 PBT；把流动性、增强体系与精密成型共同考虑。","validation":"验证薄壁充填、翘曲、紧固点疲劳及温升后的间隙；噪声需在整机上评估。","ids":[],"source":"https://www.techinherit.com/ai-hardware-cases.html"},{"id":"edge-box","title":"边缘计算设备结构件","image":"cases/ai-edge.webp","material":"PC GF20 FR","problem":"结构保护、温升和电磁相关需求容易被混为同一指标。","approach":"官网案例采用阻燃玻纤增强 PC；结构增强与 EMC 目标应分别定义和验证。","validation":"验证热循环、安装点、实际厚度阻燃及整机 EMC；玻纤增强本身不等同于屏蔽性能。","ids":[],"source":"https://www.techinherit.com/ai-hardware-cases.html"}],"electronics":[{"id":"earbuds","title":"无线耳机充电盒","image":"cases/electronics-earbuds.webp","material":"PC/ABS","problem":"小型外壳对表面、卡扣韧性和装配尺寸都有要求。","approach":"官网案例采用 PC/ABS，结合流动、冲击和外观要求安排材料与成型。","validation":"核对色差、熔接痕、开合循环和跌落后的装配；清洁介质也应纳入评估。","ids":[],"source":"https://www.techinherit.com/consumer-electronics-cases.html"},{"id":"phone-frame","title":"手机中框","image":"cases/electronics-frame.webp","material":"PA6 GF30","problem":"细长薄壁件需要刚性、平整度和精密配合。","approach":"官网案例采用 PA6 GF30；增强材料与低应力成型、纤维取向共同影响尺寸。","validation":"分别记录干态与调湿后的平整度、关键尺寸和装配应力，再核对整机功能。","ids":[],"source":"https://www.techinherit.com/consumer-electronics-cases.html"}],"furniture":[{"id":"seat-bracket","title":"座椅承载支架","image":"cases/furniture-bracket.webp","material":"PA66 GF30","problem":"长期受力、冲击与反复坐靠可能带来变形和疲劳。","approach":"官网案例采用 PA66 GF30，将刚性、韧性、热稳定与翘曲控制结合。","validation":"在实际结构上验证静载、循环疲劳、蠕变及湿度影响，关注螺钉和熔接线区域。","ids":[],"source":"https://www.techinherit.com/office-furniture-cases.html"},{"id":"armrest","title":"扶手支撑件","image":"cases/furniture-armrest.webp","material":"PA66 GF30","problem":"安装配合、受力刚性与反复接触磨损需要兼顾。","approach":"官网案例采用 PA66 GF30，围绕精密结构、承载和耐磨需求开展选型。","validation":"核对调节循环、局部承载、安装尺寸及长期使用后的松动与磨损。","ids":[],"source":"https://www.techinherit.com/office-furniture-cases.html"}],"medical":[{"id":"monitor","title":"监护设备外壳","image":"cases/medical-monitor.webp","material":"PC/ABS","problem":"反复擦拭、清洁剂接触与外观一致性是外壳选型重点。","approach":"官网案例介绍医疗用途 PC/ABS；应按实际用途核对牌号与可提供的资料。","validation":"按实际消毒剂浓度、擦拭次数和温度检查开裂、色差与尺寸；目录通用材料不代表医疗认证。","ids":[],"source":"https://www.techinherit.com/medical-devices-cases.html"},{"id":"snap-fit","title":"检测设备精密卡扣","image":"cases/medical-snap.webp","material":"POM","problem":"反复装配需要韧性、低摩擦和稳定配合。","approach":"官网案例采用医疗用途 POM；低摩擦与耐疲劳需结合结构和接触场景验证。","validation":"验证卡扣循环、插拔力和清洁相容性；患者接触用途另行确认生物相容性与法规资料。","ids":[],"source":"https://www.techinherit.com/medical-devices-cases.html"}],"pet":[{"id":"feeder","title":"自动喂食器外壳","image":"cases/pet-feeder.webp","material":"ABS","problem":"需要易清洁、外观稳定，并区分食物接触与非接触位置。","approach":"官网案例采用食品接触方向 ABS；材料牌号、颜色和接触条件需要逐项核对。","validation":"按接触时间、温度与目标市场确认迁移资料，同时评估清洗、气味和卡扣寿命。","ids":[],"source":"https://www.techinherit.com/pet-supplies-cases.html"},{"id":"crate","title":"宠物航空箱","image":"cases/pet-crate.webp","material":"PP + impact modifier","problem":"搬运跌落、承重和低温环境要求结构保持韧性。","approach":"官网案例采用增韧 PP，并结合耐候需求；材料与加强筋、锁扣结构一起评估。","validation":"在目标低温下验证整箱跌落、锁扣与承载，核对老化后的韧性和外观。","ids":[],"source":"https://www.techinherit.com/pet-supplies-cases.html"}]};
